#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_scale;
uniform float amzp_angle;
uniform float2 amzp_position;
uniform float2 amzp_stretch;
uniform float amzp_alpha;
uniform float amzp_hardness;
uniform float amzp_blendMode;
uniform float amzp_alphaComp;
uniform float amzp_cellSize;
uniform float amzp_gridType;
uniform float amzp_zigzag;
uniform float amzp_sizeFrom;
uniform float amzp_minSize;
uniform float amzp_maxSize;
uniform float amzp_contrast;
uniform float amzp_sCircle;
uniform float amzp_sSquare;
uniform float amzp_sTriangle;
uniform float amzp_sDiamond;
uniform float amzp_sStar;
uniform float amzp_sHeart;
uniform float amzp_sHexagon;
uniform float amzp_sCross;
uniform float amzp_randRot;
uniform float amzp_randSize;
uniform float amzp_jitter;
uniform float amzp_roundness;
uniform float amzp_outline;
uniform float amzp_lineWidth;
uniform float amzp_colorMode;
uniform float amzp_paletteCount;
layout(color) uniform half4 amzp_color1;
layout(color) uniform half4 amzp_color2;
layout(color) uniform half4 amzp_color3;
layout(color) uniform half4 amzp_color4;
uniform float amzp_layerTint;
uniform float amzp_background;
layout(color) uniform half4 amzp_bgColor;
uniform float amzp_clipToLayer;
uniform float amzp_evolution;
uniform float amzp_shuffle;
uniform float amzp_seed;
uniform float amzp_gradMap;
uniform float amzp_gmTri;
layout(color) uniform half4 amzp_gmFg;
layout(color) uniform half4 amzp_gmMid;
layout(color) uniform half4 amzp_gmBg;
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float2 nmRot(float2 q, float a) { float c = cos(a), s = sin(a); return float2(c * q.x - s * q.y, s * q.x + c * q.y); }
    float2 nmStd(float2 p, float pxk) {
        float z = max(amzp_scale * 2.0, 0.002);
        p -= amzp_position * pxk;
        p = nmRot(p, -radians(amzp_angle));
        return p / (z * max(amzp_stretch, float2(0.01)));
    }
    float2 nmStdUp(float2 d, float pxk) { float2 p = nmStd(float2(d.x, -d.y), pxk); return float2(p.x, -p.y); }
    float4 nmBlend(float4 tex, float4 fx) {
        float4 f = clamp(fx * amzp_hardness, 0.0, 1.0) * clamp(amzp_alpha, 0.0, 1.0);
        float4 b = tex * clamp(amzp_alphaComp, 0.0, 1.0);
        if (int(amzp_blendMode) == 0) return f;
        if (int(amzp_blendMode) == 1) return float4(b.rgb * (f.rgb + (1.0 - f.a)), b.a);
        if (int(amzp_blendMode) == 2) return float4(b.rgb + f.rgb - b.rgb * f.rgb, b.a + f.a - b.a * f.a);
        return f + b * (1.0 - f.a);
    }
    float4 nmGradMap(float4 fx) {
        if (!(amzp_gradMap>0.5)) return fx;
        float3 un = fx.a > 0.0001 ? fx.rgb / fx.a : float3(0.0);
        float v = clamp(fx.a * (0.25 + 0.75 * dot(un, float3(0.299, 0.587, 0.114))), 0.0, 1.0);
        float4 pB = float4(amzp_gmBg.rgb * amzp_gmBg.a, amzp_gmBg.a), pM = float4(amzp_gmMid.rgb * amzp_gmMid.a, amzp_gmMid.a), pF = float4(amzp_gmFg.rgb * amzp_gmFg.a, amzp_gmFg.a);
        float4 c = (amzp_gmTri>0.5) ? (v < 0.5 ? mix(pB, pM, v * 2.0) : mix(pM, pF, v * 2.0 - 1.0)) : mix(pB, pF, v);
        return c;
    }
    float2 nmStdUpInv(float2 g, float pxk) {
        float2 p = float2(g.x, -g.y) * max(amzp_scale * 2.0, 0.002) * max(amzp_stretch, float2(0.01));
        p = nmRot(p, radians(amzp_angle)) + amzp_position * pxk;
        return float2(p.x, -p.y);
    }
    float2 W;
    float4 at(float2 px) {
        float2 uv = px / W;
        if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) return float4(0.0);
        return amzTexture(0, l2s(uv));
    }
    float2 rot(float2 q, float a) { float cs = cos(a), sn = sin(a); return float2(cs * q.x - sn * q.y, sn * q.x + cs * q.y); }
    float sd0 = 0.0;
    float h1(float2 c, float k) { return fract(sin(dot(c, float2(127.1, 311.7)) + k * 17.31 + sd0 * 3.917) * 43758.5453); }
    float3 hue(float h) { return clamp(abs(mod(h * 6.0 + float3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0); }
    float sdBox(float2 p, float2 b) { float2 d = abs(p) - b; return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0); }
    float sdTri(float2 p) {
        float k = 1.7320508;
        p.y += 0.2;
        p.x = abs(p.x) - 1.0;
        p.y = p.y + 1.0 / k;
        if (p.x + k * p.y > 0.0) p = float2(p.x - k * p.y, -k * p.x - p.y) / 2.0;
        p.x -= clamp(p.x, -2.0, 0.0);
        return -length(p) * sign(p.y);
    }
    float sdStar(float2 p) {
        float r = 1.0, rf = 0.45;
        float2 k1 = float2(0.809016994, -0.587785252);
        float2 k2 = float2(-k1.x, k1.y);
        p.x = abs(p.x);
        p -= 2.0 * max(dot(k1, p), 0.0) * k1;
        p -= 2.0 * max(dot(k2, p), 0.0) * k2;
        p.x = abs(p.x);
        p.y -= r;
        float2 ba = rf * float2(-k1.y, k1.x) - float2(0.0, 1.0);
        float h = clamp(dot(p, ba) / dot(ba, ba), 0.0, r);
        return length(p - ba * h) * sign(p.y * ba.x - p.x * ba.y);
    }
    float sdHeart(float2 p) {
        p = p * 0.62 + float2(0.0, 0.52);
        p.x = abs(p.x);
        float d;
        if (p.y + p.x > 1.0) d = sqrt(dot(p - float2(0.25, 0.75), p - float2(0.25, 0.75))) - sqrt(2.0) / 4.0;
        else {
            float2 a = p - float2(0.0, 1.0);
            float2 b = p - 0.5 * max(p.x + p.y, 0.0);
            d = sqrt(min(dot(a, a), dot(b, b))) * sign(p.x - p.y);
        }
        return d / 0.62;
    }
    float sdHex(float2 p) {
        float3 k = float3(-0.866025404, 0.5, 0.577350269);
        p = abs(p);
        p -= 2.0 * min(dot(k.xy, p), 0.0) * k.xy;
        p -= float2(clamp(p.x, -k.z * 0.95, k.z * 0.95), 0.95);
        return length(p) * sign(p.y);
    }
    float sdCross(float2 p) {
        p = abs(p);
        return min(sdBox(p, float2(1.0, 0.34)), sdBox(p, float2(0.34, 1.0)));
    }
    float shapeDist(int s, float2 p, float rnd) {
        p /= (1.0 - rnd * 0.35);
        float d;
        if (s == 1) d = sdBox(p, float2(0.82 - rnd * 0.35));
        else if (s == 2) d = sdTri(p);
        else if (s == 3) d = (abs(p.x) + abs(p.y) - 1.0) * 0.7071;
        else if (s == 4) d = sdStar(p);
        else if (s == 5) d = sdHeart(p);
        else if (s == 6) d = sdHex(p);
        else if (s == 7) d = sdCross(p);
        else d = length(p) - 1.0;
        return (d - rnd * 0.35) * (1.0 - rnd * 0.35);
    }
    bool enabled(int i) {
        if (i == 0) return (amzp_sCircle>0.5);
        if (i == 1) return (amzp_sSquare>0.5);
        if (i == 2) return (amzp_sTriangle>0.5);
        if (i == 3) return (amzp_sDiamond>0.5);
        if (i == 4) return (amzp_sStar>0.5);
        if (i == 5) return (amzp_sHeart>0.5);
        if (i == 6) return (amzp_sHexagon>0.5);
        return (amzp_sCross>0.5);
    }
    int pickShape(float r) {
        float n = 0.0;
        for (int i = 0; i < 8; i++) if (enabled(i)) n += 1.0;
        if (n < 0.5) return 0;
        float want = floor(r * n);
        float c = 0.0;
        for (int i = 0; i < 8; i++) {
            if (!enabled(i)) continue;
            if (c == want) return i;
            c += 1.0;
        }
        return 0;
    }
    float valueOf(float4 c) {
        float3 s = c.a > 0.0001 ? c.rgb / c.a : float3(0.0);
        float l = dot(s, float3(0.299, 0.587, 0.114));
        if (int(amzp_sizeFrom) == 0) return (1.0 - l) * c.a;
        if (int(amzp_sizeFrom) == 1) return l * c.a;
        if (int(amzp_sizeFrom) == 2) return c.a;
        return 1.0;
    }
    void amzRender() {
        W = layer;
        float pxs = screen.zw.x / max(screen.zw.x, 1.0);
        float2 p = amzLayerNorm() * W;
        float4 src = at(p);
        float cs = max(amzp_cellSize * pxs, 2.0);
        float2 g = nmStdUp(p - 0.5 * W, pxs) / cs;
        float shuf = amzp_shuffle > 0.0 ? floor(time * amzp_shuffle) : 0.0;
        sd0 = amzp_seed + shuf * 7.123;
        float2 stz = max(amzp_scale * 2.0, 0.002) * max(amzp_stretch, float2(0.01));
        float aa = 1.0 / (cs * min(stz.x, stz.y));
        float4 acc = float4(0.0);
        float row0 = floor(g.y + 0.5);
        for (int j = -1; j <= 1; j++) {
            for (int i = -1; i <= 1; i++) {
                float ox = 0.0;
                float oy = 0.0;
                float2 c;
                if (int(amzp_gridType) == 2) {
                    float cx = floor(g.x + 0.5) + float(i);
                    oy = (mod(cx, 2.0) < 0.5 ? -0.5 : 0.5) * clamp(amzp_zigzag, 0.0, 1.0);
                    c = float2(cx, floor(g.y - oy + 0.5) + float(j));
                } else {
                    float ry = row0 + float(j);
                    ox = int(amzp_gridType) == 1 ? mod(ry, 2.0) * 0.5 : 0.0;
                    c = float2(floor(g.x - ox + 0.5) + float(i), ry);
                }
                float2 ctr = c + float2(ox, oy);
                ctr += (float2(h1(c, 1.0), h1(c, 2.0)) - 0.5) * clamp(amzp_jitter, 0.0, 1.0) * 0.8;
                float2 cpx = nmStdUpInv(ctr * cs, pxs) + 0.5 * W;
                float4 lc = at(cpx);
                if ((amzp_clipToLayer>0.5) && lc.a < 0.01) continue;
                float v = clamp(valueOf(lc), 0.0, 1.0);
                v = clamp((v - 0.5) * max(amzp_contrast, 0.1) + 0.5, 0.0, 1.0);
                float sz = mix(amzp_minSize, amzp_maxSize, v) * (1.0 - clamp(amzp_randSize, 0.0, 1.0) * h1(c, 3.0));
                if (sz <= 0.005) continue;
                float rad = sz * 0.5;
                int s = pickShape(h1(c, 4.0));
                float spinDir = h1(c, 6.0) > 0.5 ? 1.0 : -1.0;
                float an = (h1(c, 5.0) - 0.5) * 6.2831853 * clamp(amzp_randRot, 0.0, 1.0) + amzp_evolution * spinDir * (0.5 + h1(c, 7.0));
                float2 q = rot(g - ctr, -an) / rad;
                float d = shapeDist(s, q, clamp(amzp_roundness, 0.0, 1.0));
                if ((amzp_outline>0.5)) d = abs(d + amzp_lineWidth * 0.5) - amzp_lineWidth * 0.5;
                float m = 1.0 - smoothstep(-aa / rad, aa / rad, d);
                if (m <= 0.0) continue;
                float3 col;
                float hv = h1(c, 8.0);
                float3 lcol = lc.a > 0.001 ? lc.rgb / lc.a : float3(0.0);
                if (int(amzp_colorMode) == 0) {
                    float k = floor(hv * clamp(amzp_paletteCount, 1.0, 4.0));
                    col = k < 0.5 ? amzp_color1.rgb : (k < 1.5 ? amzp_color2.rgb : (k < 2.5 ? amzp_color3.rgb : amzp_color4.rgb));
                } else if (int(amzp_colorMode) == 1) col = hue(hv) * 0.85 + 0.1;
                else if (int(amzp_colorMode) == 2) col = lcol;
                else col = amzp_color1.rgb;
                if (int(amzp_colorMode) != 2) col = mix(col, col * lcol * 1.4 + lcol * 0.2, clamp(amzp_layerTint, 0.0, 1.0));
                float a = m * ((amzp_clipToLayer>0.5) ? lc.a : 1.0);
                float4 sh = float4(clamp(col, 0.0, 1.0) * a, a);
                acc = sh + acc * (1.0 - sh.a);
            }
        }
        float4 bg = float4(0.0);
        if (int(amzp_background) == 1) bg = src;
        else if (int(amzp_background) == 2) bg = float4(amzp_bgColor.rgb, 1.0) * ((amzp_clipToLayer>0.5) ? src.a : 1.0);
        amzOutput = nmBlend(bg, nmGradMap(acc));
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
